INSERT INTO "recipes" ("id","title","description","servings","prep_time","cook_time","created_at","updated_at","category") VALUES(124,'Ottolenghis Rezept: Langsames Lamm','6 Stunden schmoren, Für Starkoch Yotam Ottolenghi geht kaum etwas so gut zusammen wie Fleisch und Früchte. Heute schiebt er eine Lammschulter mit Pflaumen und Mandeln in den Ofen - und 25 Knoblauchzehen.',NULL,NULL,NULL,'2026-09-20 15:17:41','2026-09-20 15:17:41',NULL);
INSERT INTO "recipes" ("id","title","description","servings","prep_time","cook_time","created_at","updated_at","category") VALUES(125,'Fischfilet mit Orangen-Erdnusskruste','1., Fischfilets mit Zitronensaft beträufeln. Mit Salz und Pfeffer würzen. Von der Hälfte der Orangen Schale fein abreiben. Von den restlichen Orangen Schale in Zesten abziehen. Orangen auspressen. Erdnüsse in einem Cutter fein hacken. Orangenschale, die Hälfte des Safts, Wasser, wenig Olivenöl und wenig Honig dazumischen. Mit Pfeffer und einigen abgezupften Thymianblättchen aromatisieren., 2., Backofen auf 200 °C vorheizen. Restliches Öl in eine ofenfeste Form giessen. Filets in die Form legen. Erdnussmasse darauf verteilen und gut andrücken. Form in die untere Hälfte des Ofens schieben. Den Fisch 15-20 Minuten backen, bis die Kruste goldbraun ist., 3., Inzwischen Orangenzesten, restlichen Orangensaft, Wein, einige Thymianzweige und restlichen Honig in einer kleinen Pfanne aufkochen. Maisstärke in wenig Wasser auflösen. In die Sauce einrühren. Sauce kurz kochen lassen. Mit Salz und Pfeffer abschmecken., 4., Fischfilets auf der Sauce anrichten. Mit frischen Thymianzweigen servieren.',NULL,NULL,NULL,'2026-09-20 15:17:41','2026-09-20 15:17:41','Hauptgerichte');
