INSERT INTO "ingredients" ("id","name","type") VALUES(109,'Baguette',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(110,'Port-Stilton mit Lamm',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(111,'Zimt-Espresso mit Kaninchen',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(112,'Bier',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(113,'grobkörniger Senf',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(114,'Honig',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(115,'Zutaten für sechs Portionen',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(116,'1,7 kg Lammschulter mit Knochen',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(117,'25 Knoblauchzehen',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(118,'gehäutet und in einem Stück belassen',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(119,'2 Teelöffel Fenchelsamen',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(120,'1 Esslöffel ganze Thymianblätter',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(121,'2 Teelöffel Paprikapulver',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(122,'½ Teelöffel gemahlenes Kurkuma',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(123,'1 getrocknete rote Chilischote',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(124,'60 g ungesalzene Butter auf Zimmertemperatur',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(125,'750 ml trockenen Weißwein',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(126,'3 mittelgroße Zwiebeln',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(127,'grob gehackt (360 g Nettogewicht)',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(128,'20 Trockenpflaumen',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(129,'entkernt (140 g Nettogewicht)',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(130,'3 Esslöffel Olivenöl',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(131,'2 Zimtstangen',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(132,'3 Lorbeerblätter',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(133,'30 g blanchierte weiße Mandeln',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(134,'grob in Stücke von ½ cm Größe gehackt',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(135,'Salz',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(136,'Zubereitung',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(137,'Den Ofen auf 190° C vorheizen (Heißluftherd). Die Haut der Lammschulter 10 Mal mit einem scharfen Messer etwa 1 cm einschneiden und dann mit der Hautseite nach oben in einen großen',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(138,'tiefen Brater legen. Die Maße des Braters sollten etwa 40 cm mal 33 cm betragen. Acht Knoblauchzehen zusammen mit den Fenchelsamen',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(139,'Thymianblättern',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(140,'Paprikapulver',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(141,'Kurkuma',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(142,'Chilischote',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(143,'2 Teelöffeln Salz und 50 g Butter mit einem Stabmixer oder in einer Küchenmaschine zerkleinern. Die Paste mit den Händen auf der gesamten Lammschulter verteilen. Beiseite stellen und 30 Minuten bei Zimmertemperatur ruhen lassen.',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(144,'Alle übrigen Zutaten bis auf die Mandeln und die übrige Butter um die Lammschulter herum in den Brater legen. Den Wein dazugießen und genug Wasser hinzufügen',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(145,'damit die Flüssigkeit die Lammschulter zur Hälfte bedeckt. Dazu benötigen Sie etwa 750 ml Wasser.',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(146,'Ein Stück feuchtes',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(147,'fettdichtes Brotpapier direkt über die Lammschulter und die Flüssigkeit legen',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(148,'den Bräter mit zwei leicht aufgelegten Schichten Alufolie abdecken und 60 Minuten in den Ofen stellen. Die Temperatur auf 150° C reduzieren und weitere 5 Stunden braten lassen',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(149,'bis das Lammfleisch sich vom Knochen löst. Dabei ab und zu das Fett abschöpfen und bei Bedarf mehr Wasser dazugeben - falls die Flüssigkeit zu stark verdampft. Das Lamm aus dem Ofen nehmen',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(150,'auf ein separates Backblech legen und bis zum Servieren warm aufbewahren.',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(151,'Die übrige Butter in einer kleinen Pfanne zergehen lassen und die Mandeln hinzufügen. Bei mittlerer Hitze 4 bis 5 Minuten umrühren',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(152,'damit die Mandeln mit Butter umhüllt und geröstet werden. Vom Herd nehmen und ebenfalls beiseite stellen.',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(153,'Die Lorbeerblätter und Zimtstangen aus dem Saft entfernen und diesen dann in eine mittelgroße Pfanne geben: Sie sollten jetzt ungefähr 500 ml Saft haben. Auf starker Flamme schnell zum Kochen bringen und 2 Minuten kochen lassen',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(154,'bis 1/3 der Soße verdampft ist. Eventuell an der Oberfläche abgelagertes Fett entfernen.',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(155,'Das Lamm zum Servieren auf die Teller verteilen und die Soße drübergießen. Mit den Mandeln bestreuen und sofort servieren.',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(156,'Ergibt  Portionen',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(157,'4	Kabeljau-Rückenfilets à ca. 200 g',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(158,'1 EL	Zitronensaft',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(159,'Pfeffer',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(160,'2	Bio-Orangen',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(161,'150 g	geröstete',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(162,'gesalzene Erdnüsse',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(163,'4 EL	Wasser',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(164,'4 EL	Olivenöl',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(165,'3 TL	Honig',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(166,'0.5 Bund	Thymian',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(167,'1 dl	Weisswein',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(168,'1 TL	Maisstärke',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(169,'Für 4-6 Personen: 800-1000 g Secreto vom Iberico-Schwein (das sind zwei Stücke)',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(170,'1 Knoblauchzehe',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(171,'1 Rosmarinzweig',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(172,'1 TL Pimentsamen oder Wacholderbeeren',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(173,'2 EL Olivenöl',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(174,'Secreto 2 h vor dem Essen aus dem Kühlschrank nehmen',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(175,'in eine Schale legen. Die Gewürze hacken',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(176,'mit 2 EL Olivenöl mischen',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(177,'das Fleisch damit einreiben.',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(178,'Das Fleisch mit Salz und Pfeffer würzen und bei großer Hitze von beiden Seiten je etwa 4 Min. grillen. Auf einem warmen Teller ein paar Minuten ruhen lassen.',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(179,'Champignons',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(180,'Hähnchenbrustfilets',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(181,'Schweinefleisch mit Knochen',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(182,'Lammkeule ca. 2 1/2 kg',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(183,'1 1/2 kg Rinderschmorbraten',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(184,'Für 4 Personen',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(185,'600 g Lammkeule (ausgelöst und in Streifen geschnitten wie für Geschnetzeltes)',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(186,'50 ml Sojasauce (dunkel oder Tamari-Sojasauce)',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(187,'30 ml Sesamöl',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(188,'20 g Ingwer (fein gehackt)',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(189,'3 EL Kreuzkümmel (geröstet und leicht gemörsert)',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(190,'1 EL Koriandersamen (geröstet und gemörsert)',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(191,'50 ml neutrales Öl zum Braten (etwa Sonnenblume)',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(192,'4 Schalotten (in Streifen oder Ringe geschnitten)',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(193,'1 Knoblauchzehe (gehackt)',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(194,'1 Bund frischer Koriander',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(195,'einige Blätter Minze',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(196,'Die Lammstreifen mindestens 2 Stunden in dunkler Sojasauce mit Sesamöl und Ingwer marinieren. Kurz vor dem Anbraten Kreuzkümmel und Koriandersamen zum Fleisch geben und gut durchmengen. In einer Pfanne das Sonnenblumenöl erhitzen und die Lammstreifen unter Schwenken scharf anbraten. Fleisch aus der Pfanne nehmen und die Schalotten mit dem Knoblauch darin anschwitzen. Lammfleisch wieder zufügen',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(197,'mit dem geschnittenen Koriander und der Minze vermengen und servieren. Nötigenfalls mit Salz und schwarzem Pfeffer nochmals abschmecken.',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(198,'Zutaten für 4 Portionen',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(199,'1-2 kg Schweinenacken oder Schweineschulter mit Knochen (wenn Sie es noch saftiger wollen)',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(200,'Trockengewürz zum Einreiben:',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(201,'3 EL Salz',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(202,'3 EL brauner Zucker',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(203,'2 EL Kümmel',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(204,'2 EL Rosmarin',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(205,'1 EL Senfkörner',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(206,'1 EL Paprika',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(207,'1 EL Knoblauchpulver',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(208,'1 EL Zwiebelpulver',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(209,'1 EL Curry',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(210,'1 EL Cayenne-Pfeffer',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(211,'1/2 Tube Hengstenberg Delikatess-Senf Mittelscharf',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(212,'1 Beutel Hengstenberg BBQ Kraut by Mildessa',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(213,'1 Flasche Hengstenberg Milder Apfel Balsamessig',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(214,'Gemüsebrühe (im Verhältnis 1:1 zum Apfelessig)',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(215,'Zubereitungszeit: ca. 60 Minuten',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(216,'Schritt 1: Die Vorberitung',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(217,'Für die Gewürzkruste des Fleischs- im Grilljargon heißt es „Trocken-Rub” - rösten Sie alle Gewürze in einer beschichteten Pfanne 2 Minuten leicht an. Falls notwendig',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(218,'zermörsern Sie die Masse anschließend nochmal.',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(219,'Schritt 2: Das Fleisch vorbereiten',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(220,'Waschen Sie das Fleisch',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(221,'tupfen es trocken und schneiden Sie weißes Fett und die Silberhaut grob ab. Dann reiben Sie das Fleisch großzügig mit Senf und anschließend mit dem Rub ein. Wickeln Sie das marinierte Fleisch in Frischhaltefolie und legen es 12 Stunden in den Kühlschrank.',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(222,'Schritt 3: Das Fleisch garen',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(223,'Heizen Sie den Ofen auf 110 °C vor - falls möglich',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(224,'kombinieren Sie Ober- und Unterhitze mit Umluft',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(225,'ansonsten nutzen Sie nur Umlufthitze. Geben Sie die Brühe und  den Apfel Balsamessig in einen Bräter oder eine feuerfeste Schale. Der Apfel Balsamessig verdampft während des Garens nach und nach und gibt dem Fleisch später ein besonderes Aroma. Wichtig: Stechen Sie ein Thermometer mittig in das Fleisch',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(226,'bevor Sie es in den Bräter legen',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(227,'denn oft sind die Temperaturanzeigen am Ofen ungenau. Wenn das Fleisch für die Gäste am Abend fertig sein soll',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(228,'müssen Sie früh aufstehen: Bei 2 kg Fleisch beträgt die Garzeit circa 11 Stunden.',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(229,'Schritt 4: Das Fleisch pullen',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(230,'Bei 92 °C Kerntemperatur ist Ihr Fleisch fertig. Lassen Sie es nun noch etwa eine halbe Stunde in Alufolie ruhen - oder auch länger',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(231,'wenn Ihre Gäste sich verspäten. Dann können Sie es sogar noch gut in Folie und Handtüchern eingepackt ins Bett legen und dort ruhen lassen. Wenn Sie Lust haben',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(232,'pullen Sie das Fleisch später vor den Augen Ihrer Gäste - sie werden beeindruckt sein.',NULL);
INSERT INTO "ingredients" ("id","name","type") VALUES(287,'zimt',NULL);
